import {clean} from './engine.mjs';
const $=id=>document.getElementById(id),form=$('car-form');let weights,worker,pending=false,lastInput='',lastCarLabel='',currentText='';
const cars={Toyota:['Corolla','Camry','RAV4','Highlander','Prius','Tacoma','Tundra','4Runner','Sienna'],Honda:['Civic','Accord','CR-V','Fit','Pilot','Odyssey'],Ford:['F-150','Focus','Fusion','Escape','Explorer','Mustang','Ranger','Edge'],Chevrolet:['Silverado','Malibu','Equinox','Impala','Tahoe','Camaro','Cruze'],BMW:['3 Series','5 Series','X3','X5','7 Series'],Mercedes:['C-Class','E-Class','GLC','GLE','S-Class'],Audi:['A3','A4','A6','Q3','Q5','Q7'],Volkswagen:['Golf','Jetta','Passat','Tiguan','Beetle'],Nissan:['Altima','Sentra','Rogue','Pathfinder','Frontier','Leaf'],Hyundai:['Elantra','Sonata','Tucson','Santa Fe'],Kia:['Optima','Soul','Sportage','Sorento','Forte'],Subaru:['Outback','Forester','Impreza','Legacy','Crosstrek','WRX'],Mazda:['Mazda3','Mazda6','CX-5','CX-9','MX-5 Miata'],Jeep:['Wrangler','Cherokee','Grand Cherokee','Compass','Renegade'],Dodge:['Charger','Challenger','Grand Caravan','Durango'],Ram:['1500','2500','3500'],GMC:['Sierra','Terrain','Acadia','Yukon'],Lexus:['ES','IS','RX','GX','LS'],Acura:['TLX','MDX','RDX','ILX'],Volvo:['S60','S90','XC60','XC90','V60'],Tesla:['Model 3','Model S','Model X','Model Y'],Buick:['Enclave','Encore','LaCrosse'],Cadillac:['CTS','Escalade','SRX','XT5'],Chrysler:['300','Pacifica','Town & Country'],Mitsubishi:['Outlander','Lancer','Mirage'],Infiniti:['Q50','QX60','G37'],Lincoln:['MKZ','MKC','Navigator'],Porsche:['911','Cayenne','Macan','Panamera'],Other:[]};
for(const name of Object.keys(cars))$('make').add(new Option(name,name));for(let y=2026;y>=1980;y--)$('year').add(new Option(y,y));
function fillModels(){const current=$('model').value;$('model').replaceChildren();for(const n of cars[$('make').value]||[])$('model').add(new Option(n,n));$('model').add(new Option('Other — enter a model','Other'));if([...$('model').options].some(o=>o.value===current))$('model').value=current;toggleCustom();}
function toggleCustom(){$('custom-make-label').hidden=$('make').value!=='Other';$('custom-make').required=$('make').value==='Other';$('custom-model-label').hidden=$('model').value!=='Other';$('custom-model').required=$('model').value==='Other';}
function makeName(){return $('make').value==='Other'?$('custom-make').value:$('make').value;}
function modelName(){return $('model').value==='Other'?$('custom-model').value:$('model').value;}
function description(){const bits=[`${$('year').value} ${makeName()} ${modelName()} ${$('trim').value}`.replace(/\s+/g,' ').trim()+'.',`${$('mileage').value} miles.`];for(const k of ['body','fuel','transmission'])if($(k).value)bits.push($(k).value+'.');if($('condition').value)bits.push($('condition').value+' condition.');for(const k of ['title','accidents','owners','service'])if($(k).value)bits.push($(k).value+'.');const features=[...form.querySelectorAll('.equipment input:checked')].map(i=>i.value);if(features.length)bits.push(features.join(', ')+'.');if($('notes').value.trim())bits.push($('notes').value.trim());return bits.join(' ');}
function update(){currentText=description();$('text-preview').textContent=currentText;$('charcount').textContent=$('notes').value.length.toLocaleString('en-US')+' / 6,500';if(lastInput&&currentText!==lastInput&&!pending){$('status').textContent='Details changed. Estimate again to update the displayed price.';$('status').classList.remove('error');}const existing=$('scope-warning');if(existing)existing.remove();if(+($('year').value)>2021){const el=document.createElement('p');el.id='scope-warning';el.className='notice';el.textContent='This car is newer than the 2021 training snapshot. Treat its estimate as an extrapolation, not a current valuation.';$('status').after(el);}}
$('make').addEventListener('change',()=>{fillModels();update();});$('model').addEventListener('change',()=>{toggleCustom();update();});form.addEventListener('input',update);form.addEventListener('change',update);
const examples={daily:{make:'Toyota',model:'Corolla',year:'2015',trim:'SE',mileage:95000,body:'Sedan',fuel:'Gasoline',transmission:'Automatic',condition:'Good',title:'Clean title',accidents:'No accidents reported',owners:'One owner',service:'Full service history with maintenance records',features:['Air conditioning','Backup camera','New tires'],notes:'This Corolla has been my daily commuter and has mostly covered highway miles. It starts easily, shifts smoothly and tracks straight. Oil changes have been carried out on schedule, with receipts kept in a folder. The front brake pads and rotors were replaced last spring, and all four tires were replaced recently with matching all-season tires. The air conditioning blows cold and the heater works normally.\n\nThe interior is clean and has never been smoked in. There are no tears in the cloth upholstery, although the driver seat shows some normal wear. Both keys are present. The backup camera, windows, door locks and dashboard controls work. No warning lights are currently on.\n\nOutside, the paint is original to the best of my knowledge. There is a shallow scratch on the rear bumper and a small door ding on the passenger side. There is no known structural damage or flooding. The car has not been used for delivery or rideshare work. It has been parked off the street, and the underbody has no known major rust. A buyer is welcome to arrange an independent inspection. The next scheduled maintenance item is a routine oil and filter change.'},suv:{make:'Honda',model:'CR-V',year:'2017',trim:'EX-L',mileage:68000,body:'SUV',fuel:'Gasoline',transmission:'Automatic',condition:'Excellent',title:'Clean title',accidents:'No accidents reported',owners:'Two owners',service:'Full service history with maintenance records',features:['Air conditioning','Backup camera','Leather seats','Heated seats','Sunroof','All wheel drive'],notes:'Well-maintained family SUV with complete service records. Leather interior is clean, heated seats and sunroof work. Regular oil changes and recent brake service. No known mechanical faults or dashboard warning lights. A few small stone chips on the hood. Tires have good tread. Non-smoking household, both keys included.'},project:{make:'Ford',model:'Focus',year:'2010',trim:'SE',mileage:176000,body:'Sedan',fuel:'Gasoline',transmission:'Automatic',condition:'Fair',title:'Clean title',accidents:'',owners:'Three or more owners',service:'Partial service history and maintenance records',features:['Air conditioning'],notes:'Runs and drives but needs work. Check engine light is on and there is a small oil leak. Rear bumper is scratched, the driver seat has a tear and the paint is faded. Some rust near the wheel arches. Front tires will need replacement soon. Only partial service records are available. Best suited to someone prepared to inspect and repair it.'}};
function loadExample(name){const ex=examples[name];form.reset();$('make').value=ex.make;fillModels();for(const[k,v]of Object.entries(ex))if(k!=='features')$(k).value=v;for(const c of form.querySelectorAll('.equipment input'))c.checked=ex.features.includes(c.value);toggleCustom();update();$('status').textContent='Example loaded. Click Estimate asking price to run the trained models.';}
for(const b of document.querySelectorAll('[data-example]'))b.addEventListener('click',()=>loadExample(b.dataset.example));
for(const b of document.querySelectorAll('[data-view]'))b.addEventListener('click',()=>{for(const v of document.querySelectorAll('.view'))v.hidden=v.id!=='view-'+b.dataset.view;for(const n of document.querySelectorAll('nav button'))n.classList.toggle('active',n.dataset.view===b.dataset.view);window.scrollTo({top:0,behavior:'smooth'});});
const dollars=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
function display(prediction,context){$('empty-result').hidden=true;$('filled-result').hidden=false;$('result-car').textContent=lastCarLabel;$('price').textContent=dollars(Math.round(prediction.price/50)*50);$('range').textContent=prediction.range.map(n=>dollars(Math.round(n/50)*50)).join(' – ');$('context-info').textContent=`Read ${context.characters.toLocaleString('en-US')} characters · ${context.chunks} E5 ${context.chunks===1?'chunk':'chunks'}`;$('comparison').hidden=false;const domain=prediction.price<1000||prediction.price>150000;$('status').textContent=domain?'Estimate is outside the $1,000–$150,000 training price range. It is extrapolated and should be treated cautiously.':'Estimate ready. All entered details were processed in your browser.';$('status').classList.toggle('error',domain);$('estimate').disabled=false;pending=false;const changed=description()!==lastInput;if(changed)$('status').textContent='Estimate ready for the submitted details. The form has since changed; estimate again to update.';if(window.innerWidth<761)$('filled-result').scrollIntoView({behavior:'smooth',block:'center'});}
form.addEventListener('submit',e=>{e.preventDefault();if(pending||!weights||!form.reportValidity())return;const text=description();if(text.length>8000){$('status').textContent='Please shorten the description to fit the 8,000-character model limit.';return;}pending=true;lastInput=text;lastCarLabel=`${$('year').value} ${makeName()} ${modelName()}`;$('status').classList.remove('error');$('estimate').disabled=true;$('status').textContent='Preparing the long-description model…';if(!worker){worker=new Worker('/compute.mjs',{type:'module'});worker.onmessage=({data})=>{if(data.type==='progress')$('status').textContent=data.message;else if(data.type==='result')display(data.prediction,data.context);else if(data.type==='error'){pending=false;$('estimate').disabled=false;$('status').textContent='Could not calculate the estimate: '+data.message+' Your entries are preserved. Try again.';$('status').classList.add('error');}};worker.onerror=()=>{pending=false;$('estimate').disabled=false;$('status').textContent='The browser could not start E5-large. Close other tabs or use a desktop browser with more memory.';$('status').classList.add('error');worker.terminate();worker=null;};}worker.postMessage({text,requestId:Date.now()});});
$('estimate').disabled=true;fillModels();loadExample('daily');
try{const response=await fetch('/pricing-model.json');if(!response.ok)throw Error('Pricing weights are not available.');weights=await response.json();$('estimate').disabled=false;$('status').textContent='Ready. Your example is loaded; edit it or estimate its asking price.';const m=weights.meta;$('pilot-scope').textContent=`Pilot: ${m.trained_rows.toLocaleString('en-US')} retained training rows from ${m.training_candidates.toLocaleString('en-US')} candidates (50% removed), ${m.validation_rows.toLocaleString('en-US')} validation and ${m.test_rows.toLocaleString('en-US')} test listings. These scores are not directly comparable with previous full-cohort evaluations.`;$('metrics-top').innerHTML=`<div class="metric-box"><strong>${m.usable_rows.toLocaleString('en-US')}</strong><span>Filtered, deduplicated listings</span></div><div class="metric-box"><strong>${m.test_rows.toLocaleString('en-US')}</strong><span>Held-out test listings</span></div><div class="metric-box"><strong>8,000</strong><span>Characters of model input</span></div>`;{const v=m.evaluation.description_forest.test;const row=document.createElement('tr');row.className='highlight';row.innerHTML=`<td>E5-large + Extra Trees</td><td>${dollars(v.mae_usd)}</td><td>${dollars(v.rmse_usd)}</td><td>${v.median_ape_pct.toFixed(1)}%</td><td>${v.r2.toFixed(3)}</td>`;$('metrics-body').append(row);}$('band-coverage').textContent=`The validation-calibrated 80% band covered ${(100*m.band80_test_coverage).toFixed(1)}% of held-out listing prices. Training: ${m.trained_rows.toLocaleString('en-US')} listings; validation: ${m.validation_rows.toLocaleString('en-US')}; test: ${m.test_rows.toLocaleString('en-US')}.`;}catch(e){$('status').textContent='The pricing weights could not be loaded. Please refresh to retry.';$('status').classList.add('error');}
